import { describe, expect, it } from 'vitest'
import { readFileSync, existsSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { join } from 'node:path'

/**
 * Brand assets + wiring (2026-11-20): the generated icon set must exist, the
 * ICO must carry the Windows taskbar resolutions, and every branding surface
 * (exe/installer icon, window icon, AppUserModelID, UI logo) must stay wired.
 * Assets are generated by scripts/make_brand_assets.py from Logo/*.png.
 */

const ROOT = fileURLToPath(new URL('..', import.meta.url))

/** Parse an ICO: 6-byte header, then `count` 16-byte directory entries. */
function readIco(path: string): { count: number; entries: Array<{ w: number; h: number; size: number }> } {
  const data = readFileSync(path)
  if (data.readUInt16LE(0) !== 0 || data.readUInt16LE(2) !== 1) throw new Error(`${path} is not an ICO`)
  const count = data.readUInt16LE(4)
  const entries: Array<{ w: number; h: number; size: number }> = []
  for (let i = 0; i < count; i++) {
    const off = 6 + i * 16
    entries.push({
      w: data[off] === 0 ? 256 : data[off],
      h: data[off + 1] === 0 ? 256 : data[off + 1],
      size: data.readUInt32LE(off + 8)
    })
  }
  return { count, entries }
}

/** Parse a PNG header: signature + IHDR (width, height, depth, color type). */
function readPng(path: string): { width: number; height: number; bitDepth: number; colorType: number } {
  const data = readFileSync(path)
  const sig = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])
  if (!data.subarray(0, 8).equals(sig)) throw new Error(`${path} is not a PNG`)
  return {
    width: data.readUInt32BE(16),
    height: data.readUInt32BE(20),
    bitDepth: data[24],
    colorType: data[25] // 6 = truecolor RGBA
  }
}

describe('brand assets', () => {
  it('icon.ico carries the full Windows resolution set (16–256)', () => {
    const ico = readIco(join(ROOT, 'build', 'icon.ico'))
    expect(ico.count).toBeGreaterThanOrEqual(7)
    const sizes = ico.entries.map((e) => `${e.w}x${e.h}`)
    for (const s of ['16x16', '24x24', '32x32', '48x48', '64x64', '128x128', '256x256']) {
      expect(sizes).toContain(s)
    }
  })

  it('icon.png is a 512 RGBA rounded tile', () => {
    const png = readPng(join(ROOT, 'build', 'icon.png'))
    expect(png.width).toBe(512)
    expect(png.height).toBe(512)
    expect(png.colorType).toBe(6)
  })

  it('the UI logo mark is a 256 transparent PNG', () => {
    const png = readPng(join(ROOT, 'src', 'renderer', 'src', 'assets', 'logo-mark.png'))
    expect(png.width).toBe(256)
    expect(png.height).toBe(256)
    expect(png.colorType).toBe(6) // has alpha
  })

  it('the source logos in Logo/ stay untouched', () => {
    expect(existsSync(join(ROOT, 'Logo', 'vendotube-logo-aurora.png'))).toBe(true)
    expect(existsSync(join(ROOT, 'Logo', 'vendotube-logo-aurora no bg.png'))).toBe(true)
  })
})

describe('brand wiring', () => {
  it('electron-builder embeds the icon into exe + installer + uninstaller and ships it', () => {
    const yml = readFileSync(join(ROOT, 'electron-builder.yml'), 'utf8')
    expect(yml).toContain('icon: build/icon.ico')
    expect(yml).toContain('installerIcon: build/icon.ico')
    expect(yml).toContain('uninstallerIcon: build/icon.ico')
    // extraResources copies build/icon.* so window.ts can load it when packaged.
    expect(yml).toMatch(/- from: build\s*\n\s+to: build\s*\n\s+filter:\s*\n\s+- icon\.ico/)
  })

  it('the main window sets the icon (dev + packaged paths)', () => {
    const src = readFileSync(join(ROOT, 'src', 'main', 'window.ts'), 'utf8')
    expect(src).toContain('icon: windowIcon()')
    expect(src).toContain("join(process.resourcesPath, 'build', 'icon.ico')")
    expect(src).toContain("join(app.getAppPath(), 'build', 'icon.ico')")
  })

  it('the app identity matches electron-builder appId (AppUserModelID)', () => {
    const src = readFileSync(join(ROOT, 'src', 'main', 'index.ts'), 'utf8')
    expect(src).toContain("app.setAppUserModelId('studio.vendotube.app')")
    expect(readFileSync(join(ROOT, 'electron-builder.yml'), 'utf8')).toContain('appId: studio.vendotube.app')
  })

  it('the renderer uses the logo mark (TopBar + Home hero)', () => {
    const topBar = readFileSync(join(ROOT, 'src', 'renderer', 'src', 'shell', 'TopBar.tsx'), 'utf8')
    const home = readFileSync(join(ROOT, 'src', 'renderer', 'src', 'stages', 'Home.tsx'), 'utf8')
    expect(topBar).toContain("import logoMark from '../assets/logo-mark.png'")
    expect(topBar).toContain('<img src={logoMark}')
    expect(home).toContain("import logoMark from '../assets/logo-mark.png'")
    expect(home).toContain('<img src={logoMark}')
  })
})
